// ---- copy buttons
function copyText(text, btn){
  const done = () => { const o = btn.textContent; btn.textContent = lang==='ar' ? 'تم النسخ' : 'Copied'; setTimeout(()=>btn.textContent=o,1500); };
  if (navigator.clipboard) navigator.clipboard.writeText(text).then(done).catch(()=>{});
}
document.querySelectorAll('[data-copy]').forEach(b => b.addEventListener('click', () => copyText(b.dataset.copy, b)));

// ---- lead form (sent by email via Netlify Forms)
const form = document.getElementById('leadForm');
function buildMsg(){
  if (!form) return '';
  const f = new FormData(form);
  const checked = [...form.querySelectorAll('input[name=need]:checked')];
  const sel = id => { const s = document.getElementById(id); return s.options[s.selectedIndex].text; };
  const needs = lang === 'ar' ? checked.map(i => i.nextElementSibling.textContent).join('، ') : checked.map(i => i.value).join(', ');
  const lines = lang === 'ar' ? [
    'مرحباً ويز للخدمات الذكية، أرسلت استفساراً عبر الموقع.',
    'الاسم: ' + f.get('name'), 'البريد: ' + f.get('email'), 'النشاط: ' + f.get('act'), 'الدولة المستهدفة: ' + sel('f_mkt'),
    'الخدمات: ' + (needs || 'لم أحدد')
  ] : [
    'Hello Wizz Smart Services, I sent an enquiry through the website.',
    'Name: ' + f.get('name'), 'Email: ' + f.get('email'), 'Activity: ' + f.get('act'), 'Target country: ' + sel('f_mkt'),
    'Services: ' + (needs || 'Not sure yet')
  ];
  const text = lines.join('\n');
  const wa = document.getElementById('waLink'); if (wa) wa.href = 'https://wa.me/601124477685?text=' + encodeURIComponent(text);
  return text;
}
if (form) {
  const emailOk = v => /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v);
  form.addEventListener('submit', async e => {
    e.preventDefault();
    const fail = document.getElementById('formFail'); fail.hidden = true;
    const req = ['f_name','f_email','f_nat','f_res','f_act'].filter(id => {
      const v = document.getElementById(id).value.trim(); return id === 'f_email' ? !emailOk(v) : !v; });
    document.getElementById('formErr').hidden = req.length === 0;
    if (req.length) { document.getElementById(req[0]).focus(); return; }
    const services = [...form.querySelectorAll('input[name=need]:checked')].map(i => i.value).join(', ') || 'Not sure yet';
    form.elements.services.value = services;
    form.elements.lang.value = lang;
    form.elements.subject.value = 'Website enquiry: ' + form.elements.name.value.trim() + ' (' + form.elements.mkt.value + ')';
    const data = new FormData(form); data.delete('need');
    const btn = form.querySelector('button[type=submit]'); const lbl = btn.querySelector('[data-i18n]');
    btn.disabled = true; const old = lbl.textContent; lbl.textContent = lang === 'ar' ? 'جارٍ الإرسال…' : 'Sending…';
    try {
      // 1) email the team (and the client) through our function; 2) if that fails, keep the lead in Netlify Forms
      let sent = false;
      try {
        const r = await fetch('/.netlify/functions/contact', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(Object.fromEntries(data)) });
        sent = r.ok;
      } catch (_) {}
      if (!sent) {
        const r = await fetch('/', { method: 'POST', headers: { 'Content-Type': 'application/x-www-form-urlencoded' }, body: new URLSearchParams(data).toString() });
        if (!r.ok) throw new Error('HTTP ' + r.status);
      }
      buildMsg();
      form.querySelectorAll(':scope > div:not(.out), :scope > fieldset, :scope > p').forEach(n => n.hidden = true);
      const out = document.getElementById('out'); out.hidden = false;
      out.scrollIntoView({behavior:'smooth', block:'center'}); out.focus({preventScroll:true});
      if (window.gtag) gtag('event', 'generate_lead', { form: 'contact' });
    } catch (err) {
      fail.hidden = false;
    } finally { btn.disabled = false; lbl.textContent = old; }
  });
}

// ---- hero route map
(function drawMap(){
  const svg = document.getElementById('routeMap'); if (!svg) return;
  const X = lon => 20 + (lon + 135) / 275 * 560, Y = lat => 30 + (68 - lat) / 78 * 360;
  const NS = 'http://www.w3.org/2000/svg';
  const el = (n, a, parent = svg) => { const e = document.createElementNS(NS, n); for (const k in a) e.setAttribute(k, a[k]); parent.appendChild(e); return e; };
  const g = el('g', {});
  for (let lon = -120; lon <= 120; lon += 30) el('line', {x1:X(lon), y1:Y(68), x2:X(lon), y2:Y(-10), class:'grat'}, g);
  for (const lat of [60, 30, 0]) el('line', {x1:X(-135), y1:Y(lat), x2:X(140), y2:Y(lat), class:'grat', ...(lat === 0 ? {'stroke-dasharray':'2 4'} : {})}, g);
  const eq = el('text', {x:X(-133), y:Y(0) - 6, class:'eqlbl'}, g); eq.textContent = '0°';
  const OFF = {US:[-26,16], CA:[8,-6], UK:[-26,-4], FR:[-24,14], NL:[4,-9], PL:[8,12], EE:[8,-4], SA:[-26,6], AE:[2,-9], OM:[8,14], PK:[8,-4], TH:[-26,4]};
  const hubN = MAP_NODES.find(n => n.c === 'MY'); const hub = {x:X(hubN.lon), y:Y(hubN.lat)};
  const arcs = el('g', {});
  MAP_NODES.filter(n => n.c !== 'MY').forEach((d, i) => {
    const x = X(d.lon), y = Y(d.lat); d.x = x; d.y = y;
    const dist = Math.hypot(x - hub.x, y - hub.y);
    const mx = (x + hub.x) / 2, my = Math.min(y, hub.y) - (dist * 0.28 + 16);
    el('path', {d:`M${hub.x},${hub.y} Q${mx},${my} ${x},${y}`, class:'arc', style:`animation-delay:${-i*0.3}s`}, arcs);
  });
  MAP_NODES.filter(n => n.c !== 'MY').forEach(d => {
    el('circle', {cx:d.x, cy:d.y, r:3.6, class:'ndot'});
    const o = OFF[d.c] || [8, -6];
    const t = el('text', {x:d.x + o[0], y:d.y + o[1], class:'clabel'}); t.textContent = d.c;
  });
  el('circle', {cx:hub.x, cy:hub.y, r:7, class:'pulse'});
  el('circle', {cx:hub.x, cy:hub.y, r:7, class:'hub'});
  const ht = el('g', {class:'tag hubtag', transform:`translate(${hub.x - 118},${hub.y + 14})`});
  el('rect', {x:0, y:0, width:128, height:34, rx:3}, ht);
  const h1 = el('text', {x:8, y:15}, ht); h1.textContent = 'KUALA LUMPUR';
  const h2 = el('text', {x:8, y:27, class:'sub'}, ht); h2.textContent = 'Wizz HQ · Malaysia';
})();

// ---- filters (countries / marketplaces)
document.querySelectorAll('[data-filter-group]').forEach(group => {
  const target = document.querySelector(`[data-filter-target="${group.dataset.filterGroup}"]`); if (!target) return;
  const apply = key => {
    group.querySelectorAll('.chip').forEach(c => { const on = c.dataset.filter === key; c.classList.toggle('on', on); c.setAttribute('aria-pressed', on ? 'true' : 'false'); });
    [...target.children].forEach(card => { card.hidden = !(key === 'all' || card.dataset.group === key || card.dataset.group === 'all'); });
  };
  group.addEventListener('click', e => {
    const b = e.target.closest('.chip'); if (!b) return;
    apply(b.dataset.filter);
    try { history.replaceState(null, '', b.dataset.filter === 'all' ? location.pathname : '#' + b.dataset.filter); } catch(err) {}
  });
  const h = location.hash.slice(1);
  if (h && group.querySelector(`[data-filter="${h}"]`)) apply(h);
});

// ---- services page: highlight the section in view
(function(){
  const links = [...document.querySelectorAll('.svc-index a')]; if (!links.length || !('IntersectionObserver' in window)) return;
  const io = new IntersectionObserver(entries => {
    entries.forEach(en => { if (en.isIntersecting) links.forEach(a => a.classList.toggle('on', a.getAttribute('href') === '#' + en.target.id)); });
  }, {rootMargin:'-30% 0px -60% 0px'});
  document.querySelectorAll('.srow').forEach(r => io.observe(r));
})();
